1	// The printer form: "Browse the full printer list" in the printer panel's
2	// header opens it over the conversation, for a person who would rather pick
3	// their printer than describe it. Three steps, as the canvas's Add a printer
4	// boards draw them -- which printer, which plate, which filament to start
5	// with -- and the plate step only where OrcaSlicer offers a plate choice.
6	//
7	// Everything it offers comes from the app (PrinterConversation::form_json):
8	// the catalogue, the Bambu Lab printers found on the network, and for the
9	// chosen model and nozzle the plates and compatible filaments OrcaSlicer
10	// would offer. Nothing is saved until the last step; closing it changes
11	// nothing.
12	
13	import { useEffect, useMemo, useState } from 'react';
14	import type { PrinterFormInfo, PrinterFormModel, PrinterFormOptions } from '../bridge/protocol';
15	import { ActionMenu, Dialog } from './ChatNavigation';
16	
17	export interface PrinterFormChoice {
18	  catalogId: string;
19	  nozzle: number;
20	  plate?: number;
21	  filament?: string;
22	  deviceId?: string;
23	}
24	
25	type Step = 'printer' | 'plate' | 'filament';
26	
27	// Search results drawn at once; the rest wait for a narrower search.
28	const RESULT_LIMIT = 50;
29	
30	const byName = (a: string, b: string) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
31	
32	// 0.4 where the model ships it, as the chat assumes, otherwise its smallest.
33	function startingNozzle(model: PrinterFormModel): number {
34	  return model.nozzles.includes(0.4) ? 0.4 : model.nozzles[0];
35	}
36	
37	function StepMarker({ step, steps }: { step: number; steps: number }) {
38	  return <div className="printer-form-step">
39	    <span>Step {step} of {steps}</span>
40	    <span className="printer-form-dots" aria-hidden="true">
41	      {Array.from({ length: steps }, (_, index) =>
42	        <span key={index} className={index < step ? 'printer-form-dot done' : 'printer-form-dot'} />)}
43	    </span>
44	  </div>;
45	}
46	
47	export function AddPrinterForm({ form, onAsk, onFinish, onClose }: {
48	  form: PrinterFormInfo;
49	  onAsk: (catalogId: string, nozzle: number) => void;
50	  onFinish: (choice: PrinterFormChoice) => void;
51	  onClose: () => void;
52	}) {
53	  const [vendorId, setVendorId] = useState<string>();
54	  const [catalogId, setCatalogId] = useState<string>();
55	  const [nozzle, setNozzle] = useState<number>();
56	  const [deviceId, setDeviceId] = useState<string>();
57	  const [step, setStep] = useState<Step>('printer');
58	  const [plate, setPlate] = useState<number>();
59	  const [query, setQuery] = useState('');
60	  // Finishing waits for the app: it either closes the form or says why not.
61	  const [finishing, setFinishing] = useState(false);
62	  useEffect(() => { setFinishing(false); }, [form.error]);
63	
64	  // One brand per vendor file: a vendor whose model names spell the brand
65	  // two ways is still one brand.
66	  const brands = useMemo(() => {
67	    const seen = new Map<string, string>();
68	    for (const model of form.catalog) if (!seen.has(model.vendorId)) seen.set(model.vendorId, model.brand);
69	    return [...seen].map(([id, label]) => ({ id, label })).sort((a, b) => byName(a.label, b.label));
70	  }, [form.catalog]);
71	  const models = useMemo(() => form.catalog.filter((model) => model.vendorId === vendorId)
72	    .sort((a, b) => byName(a.model, b.model)), [form.catalog, vendorId]);
73	  const model = form.catalog.find((entry) => entry.id === catalogId);
74	
75	  useEffect(() => { if (catalogId && nozzle !== undefined) onAsk(catalogId, nozzle); }, [catalogId, nozzle]);
76	
77	  // The options the app sent for exactly this choice, and none for another.
78	  const options: PrinterFormOptions | undefined =
79	    form.options && form.options.catalogId === catalogId && form.options.nozzle === nozzle ? form.options : undefined;
80	  const ready = options !== undefined && !form.loading;
81	  const offersPlates = ready && options.plates.length > 0;
82	  const steps = ready && !offersPlates ? 2 : 3;
83	
84	  // Moving on before the options arrived lands on the plate step, which
85	  // gives way to the filament step once it is clear there is no plate to ask.
86	  useEffect(() => {
87	    if (step === 'plate' && ready && !offersPlates) setStep('filament');
88	  }, [step, ready, offersPlates]);
89	  useEffect(() => {
90	    if (!options) return;
91	    setPlate(options.plates.some((entry) => entry.type === options.defaultPlate) ? options.defaultPlate : options.plates[0]?.type);
92	  }, [options?.catalogId, options?.nozzle]);
93	
94	  const chooseModel = (entry: PrinterFormModel, device?: string) => {
95	    setVendorId(entry.vendorId);
96	    setCatalogId(entry.id);
97	    setNozzle(startingNozzle(entry));
98	    setDeviceId(device);
99	  };
100	
101	  const finish = (filament?: string) => {
102	    if (!catalogId || nozzle === undefined || !options) return;
103	    setFinishing(true);
104	    onFinish({ catalogId, nozzle, ...(offersPlates ? { plate } : {}), ...(filament ? { filament } : {}),
105	      ...(deviceId ? { deviceId } : {}) });
106	  };
107	
108	  const loadingNote = !options || form.loading
109	    ? <p className="printer-form-note">Reading this printer’s profiles…</p>
110	    : options.error ? <p className="printer-form-error" role="alert">{options.error}</p> : null;
111	  const errorNote = form.error ? <p className="printer-form-error" role="alert">{form.error}</p> : null;
112	
113	  if (step === 'printer') {
114	    return <Dialog key="printer" title="Which printer?" onClose={onClose} className="printer-form"
115	      eyebrow={<StepMarker step={1} steps={steps} />}>
116	      <div className="printer-form-fields">
117	        <div className="printer-form-field">
118	          <span className="printer-form-label">Brand</span>
119	          <ActionMenu label="Brand" appearance="select" text={brands.find((brand) => brand.id === vendorId)?.label ?? 'Choose a brand'}
120	            search={{ label: 'Search brands', noMatch: (text) => `No brand matches “${text}”` }}
121	            items={brands.map((brand) => ({ key: brand.id, label: brand.label, current: brand.id === vendorId,
122	              onSelect: () => {
123	                if (brand.id === vendorId) return;
124	                setVendorId(brand.id);
125	                setCatalogId(undefined);
126	                setNozzle(undefined);
127	                setDeviceId(undefined);
128	              } }))} />
129	        </div>
130	        <div className="printer-form-field">
131	          <span className="printer-form-label">Model</span>
132	          <ActionMenu label="Model" appearance="select" disabled={!vendorId} text={model?.model ?? 'Choose a model'}
133	            search={{ label: 'Search models', noMatch: (text) => `No model matches “${text}”` }}
134	            items={models.map((entry) => ({ key: entry.id, label: entry.model, current: entry.id === catalogId,
135	              onSelect: () => { if (entry.id !== catalogId) chooseModel(entry); } }))} />
136	        </div>
137	        {model && <div className="printer-form-field">
138	          <span className="printer-form-label">Nozzle</span>
139	          {model.nozzles.length > 1
140	            ? <div className="jp-segmented printer-form-nozzles" role="radiogroup" aria-label="Nozzle">
141	                {model.nozzles.map((size) => <button type="button" key={size} role="radio" aria-checked={size === nozzle}
142	                  className={size === nozzle ? 'jp-segment selected' : 'jp-segment'} onClick={() => setNozzle(size)}>
143	                  {size}</button>)}
144	              </div>
145	            : <p className="printer-form-value">{model.nozzles[0]} mm, the only size it comes with</p>}
146	        </div>}
147	      </div>
148	      {form.nearby.length > 0 && <>
149	        <hr className="printer-form-rule" />
150	        <div className="printer-form-found">
151	          <span className="printer-form-heading">Found on your network</span>
152	          {form.nearby.map((found) => {
153	            const entry = form.catalog.find((item) => item.id === found.catalogId);
154	            return <button type="button" key={found.deviceId} className="printer-form-row" aria-pressed={found.deviceId === deviceId}
155	              onClick={() => { if (entry) chooseModel(entry, found.deviceId); }}>
156	              <span className="printer-form-row-name">{entry ? `${entry.brand} ${entry.model}` : found.name} · {found.deviceId}</span>
157	              <span className="printer-form-online" aria-label="On the network" />
158	            </button>;
159	          })}
160	          <p className="printer-form-note printer-form-center">You can connect it later.</p>
161	        </div>
162	      </>}
163	      {errorNote}
164	      <div className="chat-dialog-buttons">
165	        <button type="button" onClick={onClose}>Cancel</button>
166	        <button type="button" className="primary" disabled={!model || nozzle === undefined} onClick={() => setStep('plate')}>Next</button>
167	      </div>
168	    </Dialog>;
169	  }
170	
171	  if (step === 'plate') {
172	    return <Dialog key="plate" title="Which plate is on it?" onClose={onClose} className="printer-form"
173	      eyebrow={<StepMarker step={2} steps={steps} />}>
174	      {loadingNote ?? <div className="printer-form-choices" role="radiogroup" aria-label="Plate">
175	        {options!.plates.map((entry) => <button type="button" key={entry.type} role="radio" aria-checked={entry.type === plate}
176	          className="printer-form-choice" onClick={() => { setPlate(entry.type); setStep('filament'); }}>
177	          <span className="printer-form-choice-name">{entry.label}</span>
178	          {entry.type === options!.defaultPlate && <span className="printer-form-choice-detail">Default for the {model?.model}</span>}
179	        </button>)}
180	      </div>}
181	      <div className="chat-dialog-buttons">
182	        <button type="button" onClick={() => setStep('printer')}>Back</button>
183	        <button type="button" onClick={onClose}>Cancel</button>
184	      </div>
185	    </Dialog>;
186	  }
187	
188	  const filaments = options?.filaments ?? [];
189	  const wanted = query.trim().toLowerCase();
190	  const matches = wanted
191	    ? filaments.filter((entry) => [entry.label, entry.vendor, entry.material].some((text) => text.toLowerCase().includes(wanted)))
192	    : [];
193	  const suggested = (options?.suggested.length ? options.suggested : options?.defaultFilament ? [options.defaultFilament] : [])
194	    .map((name) => filaments.find((entry) => entry.name === name))
195	    .filter((entry): entry is PrinterFormOptions['filaments'][number] => entry !== undefined);
196	  const shownList = wanted ? matches.slice(0, RESULT_LIMIT) : suggested;
197	  const defaultLabel = filaments.find((entry) => entry.name === options?.defaultFilament)?.label;
198	
199	  return <Dialog key="filament" title="Which filament do you want to start with?" onClose={onClose} className="printer-form"
200	    eyebrow={<StepMarker step={steps} steps={steps} />}>
201	    {loadingNote ?? <>
202	      <label className="field-search">
203	        <span className="jp-icon jp-icon-search" aria-hidden="true" />
204	        <input type="search" placeholder="Search brand or material" aria-label="Search brand or material" value={query}
205	          onChange={(event) => setQuery(event.target.value)} />
206	      </label>
207	      <div className="printer-form-list">
208	        <span className="printer-form-heading">{wanted ? 'Matches' : `Suggested for the ${model?.model}`}</span>
209	        {shownList.map((entry) => <button type="button" key={entry.name} className="printer-form-row" disabled={finishing}
210	          onClick={() => finish(entry.name)}>
211	          <span className="printer-form-row-copy">
212	            <span className="printer-form-row-title">{entry.label}</span>
213	            <span className="printer-form-row-detail">{[entry.vendor, entry.material].filter(Boolean).join(' · ')}</span>
214	          </span>
215	          <span className="jp-icon jp-icon-chevron-right" aria-hidden="true" />
216	        </button>)}
217	        {wanted && matches.length === 0 && <p className="printer-form-note">No filament for this printer matches “{query.trim()}”.</p>}
218	        {matches.length > RESULT_LIMIT && <p className="printer-form-note">
219	          {matches.length - RESULT_LIMIT} more match. Type more to narrow the list.</p>}
220	      </div>
221	      <button type="button" className="panel-link-button printer-form-skip" disabled={finishing} onClick={() => finish()}>
222	        {defaultLabel ? `Skip — start with ${defaultLabel}` : 'Skip — choose a filament later'}
223	      </button>
224	    </>}
225	    {errorNote}
226	    <div className="chat-dialog-buttons">
227	      <button type="button" onClick={() => setStep(offersPlates ? 'plate' : 'printer')}>Back</button>
228	      <button type="button" onClick={onClose}>Cancel</button>
229	    </div>
230	  </Dialog>;
231	}
