cd /Users/kenneth/Projects/JusPrin/.claude/worktrees/filament-step-design-918d1e/resources/profiles && ls Anycubic/machine | grep -i "4max" ; python3 - <<'EOF'
import json,glob,re,collections
P={}
for d in ['Anycubic/filament','OrcaFilamentLibrary/filament']:
    for f in glob.glob(d+'/**/*.json',recursive=True):
        try: j=json.load(open(f))
        except: continue
        if j.get('type')=='filament': P[j['name']]=j
def get(n,k,d=0):
    p=P.get(n)
    if not p or d>20: return None
    return p[k] if k in p else (get(p['inherits'],k,d+1) if 'inherits' in p else None)
pr="Anycubic 4Max Pro 2 0.4 nozzle"
comp=set(); inc=collections.defaultdict(set)
for n in P:
    if str(get(n,'instantiation')).lower()!='true': continue
    cp=get(n,'compatible_printers') or []; cond=get(n,'compatible_printers_condition') or ''
    a=n.split(' @')[0]
    if (not cp and not cond) or pr in cp: comp.add(a)
    else:
        for c in cp: inc[a].add(re.sub(r' ?\d\.\d+ nozzle$','',c))
only={a:s for a,s in inc.items() if a not in comp}
print(len(comp),'fit;',len(only),'only for other printers')
for a in sorted(only): print(' ',a,'->',sorted(only[a])[:4])
EOF

